=== FILE: period_calc.py ===
"""Low-level timestamp window evaluator."""
def check_in_window(start_ts: int, end_ts: int, probe_ts: int) -> bool:
    # Rule H05: Standard query intervals (like subscription entitlements) must follow
    # the half-open interval convention [start, end), meaning start <= t < end.
    return start_ts <= probe_ts < end_ts

def get_window_duration(start_ts: int, end_ts: int) -> int:
    return max(0, end_ts - start_ts)

def is_valid_epoch_range(start_ts: int, end_ts: int) -> bool:
    # For a half-open interval [start, end), end can be equal to start for an empty window.
    # So, end_ts >= start_ts is still correct for validity.
    return end_ts >= start_ts >= 0
